export function aiDemandSvg(lang, kind, mobile = false) {
  if (typeof lang !== 'string' || !['fr', 'en'].includes(lang) || typeof kind !== 'string' || !AI_DEMAND_KINDS.includes(kind) || typeof mobile !== 'boolean') throw new TypeError('Invalid AI demand figure variant');
  return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
